pub fn poseidon_config_f257() -> PoseidonConfig<F257> {
    // Convert u16 constants into field elements.
    let mds: Vec<Vec<F257>> = MDS_U16
        .iter()
        .map(|row| row.iter().map(|&x| F257::from(x as u64)).collect())
        .collect();

    let ark: Vec<Vec<F257>> = ARK_U16
        .iter()
        .map(|row| row.iter().map(|&x| F257::from(x as u64)).collect())
        .collect();

    PoseidonConfig::<F257>::new(
        FULL_ROUNDS,
        PARTIAL_ROUNDS,
        ALPHA,
        mds,
        ark,
        RATE,
        CAPACITY,
    )
}
